/* Minecraft-style crafting popups for the wiki.
 *
 * Every item that has a recipe becomes clickable: the tables on items.html, plus mentions of
 * item names in the running text. Clicking one opens a 3x3 crafting grid built from
 * docs/recipes-data.js (generated by tools/build_docs_recipes.py).
 */
(function () {
  'use strict';

  var data = window.NARUTO_RECIPES;
  if (!data || !data.recipes) return;

  var byId = data.recipes;
  var byShort = new Map();
  Object.keys(byId).forEach(function (id) {
    byShort.set(id.split(':').pop(), id);
  });

  var modal = null;
  var panel = null;
  var lastFocus = null;

  function escapeHtml(text) {
    return String(text == null ? '' : text)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }
  function recipeFor(short) {
    var id = byShort.get(short) || (/^narutomod:/.test(short) ? short : null);
    return id && byId[id] ? { id: id, recipes: byId[id] } : null;
  }
  function iconHtml(entry, extraClass) {
    if (!entry) return '';
    if (entry.icon) {
      return '<img src="' + escapeHtml(entry.icon) + '" alt="" loading="lazy" class="' +
        (extraClass || '') + '">';
    }
    var letter = (entry.name || '?').trim().charAt(0).toUpperCase();
    return '<span class="craft__letter" aria-hidden="true">' + escapeHtml(letter) + '</span>';
  }

  function slotHtml(id, count) {
    if (!id) return '<div class="craft__slot craft__slot--empty" aria-hidden="true"></div>';
    var name = (data.names && data.names[id]) || id.split(':').pop().replace(/_/g, ' ');
    var icon = (data.icons && data.icons[id]) || null;
    var entry = { icon: icon, name: name };
    return '<div class="craft__slot" title="' + escapeHtml(entry.name) + '">' +
      iconHtml(entry) + (count > 1 ? '<span class="craft__count">' + count + '</span>' : '') +
      '</div>';
  }

  function totals(recipe) {
    var counts = new Map();
    recipe.ingredients.forEach(function (ing) {
      counts.set(ing.id, (counts.get(ing.id) || 0) + 1);
    });
    return Array.from(counts.entries()).map(function (pair) {
      var entry = recipe.ingredients.find(function (ing) { return ing.id === pair[0]; });
      return { id: pair[0], name: entry ? entry.name : pair[0], icon: entry ? entry.icon : null, count: pair[1] };
    });
  }

  function render(id, index) {
    var set = byId[id];
    if (!set || !set.length) return;
    var recipe = set[Math.min(index || 0, set.length - 1)];

    var cells = recipe.grid.map(function (slot) {
      return slotHtml(slot || null, 1);
    }).join('');

    var rows = totals(recipe).map(function (ing) {
      return '<li>' + escapeHtml(ing.name) + (ing.count > 1 ? ' × ' + ing.count : '') + '</li>';
    }).join('');

    var variants = set.length > 1 ? '<div class="craft__variants" role="group" aria-label="Варианты крафта">' +
      set.map(function (_, i) {
        return '<button type="button" class="craft__variant' + (i === index ? ' on' : '') +
          '" data-craft-variant="' + i + '">Вариант ' + (i + 1) + '</button>';
      }).join('') + '</div>' : '';

    panel.innerHTML =
      '<div class="craft__head">' +
      '<h2 class="craft__title" id="craft-title">' + escapeHtml(recipe.name) + '</h2>' +
      '<button type="button" class="craft__close" data-craft-close aria-label="Закрыть">×</button>' +
      '</div>' +
      '<div class="craft__body">' +
      '<div class="craft__row">' +
      '<div class="craft__grid" role="img" aria-label="Сетка крафта 3 на 3">' + cells + '</div>' +
      '<div class="craft__arrow" aria-hidden="true">➜</div>' +
      '<div class="craft__slot craft__result" title="' + escapeHtml(recipe.name) + '">' +
      (recipe.icon
        ? '<img src="' + escapeHtml(recipe.icon) + '" alt="" class="craft__result-icon">'
        : '<span class="craft__letter">' + escapeHtml(recipe.name.charAt(0).toUpperCase()) + '</span>') +
      (recipe.count > 1 ? '<span class="craft__count">' + recipe.count + '</span>' : '') +
      '</div>' +
      '</div>' +
      '<p class="craft__meta">' + escapeHtml(recipe.name) +
      (recipe.count > 1 ? ' <strong>× ' + recipe.count + '</strong>' : '') + '</p>' +
      '<p class="craft__note">' + (recipe.shaped
        ? 'Форменный крафт: предметы кладутся ровно так, как на сетке.'
        : 'Бесформенный крафт: порядок ингредиентов не важен.') + '</p>' +
      variants +
      (rows ? '<ul class="craft__list">' + rows + '</ul>' : '') +
      '</div>';

    panel.querySelector('[data-craft-close]').addEventListener('click', close);
    panel.querySelectorAll('[data-craft-variant]').forEach(function (button) {
      button.addEventListener('click', function () {
        render(id, parseInt(button.getAttribute('data-craft-variant'), 10));
      });
    });
  }

  function open(id, index) {
    var set = byId[id];
    if (!set) return;
    lastFocus = document.activeElement;
    if (!modal) {
      modal = document.createElement('div');
      modal.className = 'craft-modal';
      modal.setAttribute('role', 'dialog');
      modal.setAttribute('aria-modal', 'true');
      modal.setAttribute('aria-labelledby', 'craft-title');
      panel = document.createElement('div');
      panel.className = 'craft';
      modal.appendChild(panel);
      modal.addEventListener('click', function (event) {
        if (event.target === modal) close();
      });
      document.body.appendChild(modal);
      document.addEventListener('keydown', onKey);
    }
    modal.hidden = false;
    render(id, index || 0);
    var closeButton = panel.querySelector('[data-craft-close]');
    if (closeButton) closeButton.focus();
    document.documentElement.style.overflow = 'hidden';
  }

  function close() {
    if (!modal) return;
    modal.hidden = true;
    document.documentElement.style.overflow = '';
    if (lastFocus && lastFocus.focus) lastFocus.focus();
    lastFocus = null;
  }

  function onKey(event) {
    if (event.key === 'Escape') { close(); return; }
    if (event.key !== 'Tab' || !modal || modal.hidden) return;
    var focusables = panel.querySelectorAll('button, [href], input, [tabindex]:not([tabindex="-1"])');
    if (!focusables.length) return;
    var first = focusables[0], last = focusables[focusables.length - 1];
    if (event.shiftKey && document.activeElement === first) { last.focus(); event.preventDefault(); }
    else if (!event.shiftKey && document.activeElement === last) { first.focus(); event.preventDefault(); }
  }

  document.addEventListener('click', function (event) {
    var trigger = event.target.closest('[data-item]');
    if (!trigger) return;
    event.preventDefault();
    open(trigger.getAttribute('data-item'));
  });

  // --- table wiring ----------------------------------------------------------------------------

  function wireTables() {
    document.querySelectorAll('td.mono, td.mono.small').forEach(function (cell) {
      var short = cell.textContent.trim().split(':').pop();
      if (!byShort.has(short)) return;
      var id = byShort.get(short);
      var row = cell.closest('tr');
      if (!row) return;
      var nameCell = row.querySelector('td');
      if (nameCell && !nameCell.querySelector('[data-item]')) {
        nameCell.innerHTML = '<button type="button" class="item-link" data-item="' +
          escapeHtml(id) + '" title="Показать крафт">' + nameCell.innerHTML + '</button>';
      }
      if (!cell.querySelector('[data-item]')) {
        cell.innerHTML = '<button type="button" class="item-link" data-item="' +
          escapeHtml(id) + '" title="Показать крафт">' + escapeHtml(cell.textContent.trim()) +
          '</button>';
      }
    });
  }

  // --- name links in the running text ----------------------------------------------------------

  function linkNames() {
    var main = document.querySelector('main.doc') || document.querySelector('.doc');
    if (!main || !data.aliases) return;
    var aliases = Object.keys(data.aliases).sort(function (a, b) { return b.length - a.length; });
    if (!aliases.length) return;

    var pattern;
    try {
      pattern = new RegExp('(?<![\\p{L}\\p{N}_-])(' + aliases.map(function (text) {
        return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      }).join('|') + ')(?![\\p{L}\\p{N}_-])', 'giu');
    } catch (error) {
      return;
    }

    var skip = new Set(['A', 'CODE', 'KBD', 'PRE', 'SCRIPT', 'STYLE', 'TEXTAREA', 'BUTTON',
      'H1', 'H2', 'H3', 'H4', 'TH']);
    var walker = document.createTreeWalker(main, NodeFilter.SHOW_TEXT, {
      acceptNode: function (node) {
        var parent = node.parentNode;
        if (!parent || skip.has(parent.nodeName)) return NodeFilter.FILTER_REJECT;
        if (parent.closest('[data-item], .item-link, .combo, .no-craft, .callout__title')) return NodeFilter.FILTER_REJECT;
        if (!node.nodeValue || node.nodeValue.length < 5) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });

    var targets = [];
    while (walker.nextNode()) targets.push(walker.currentNode);

    var made = 0;
    targets.forEach(function (node) {
      if (made > 120) return;
      var text = node.nodeValue;
      var pieces = [];
      var last = 0;
      var match;
      pattern.lastIndex = 0;
      while ((match = pattern.exec(text)) !== null) {
        var id = data.aliases[match[1].toLowerCase()] ||
          data.aliases[match[1].toLowerCase().replace(/ё/g, 'е')];
        if (!id || match.index <= last - 1) continue;
        pieces.push(document.createTextNode(text.slice(last, match.index)));
        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'item-link';
        button.setAttribute('data-item', id);
        button.setAttribute('title', 'Показать крафт');
        button.textContent = match[1];
        pieces.push(button);
        last = match.index + match[1].length;
        made += 1;
      }
      if (!pieces.length) return;
      pieces.push(document.createTextNode(text.slice(last)));
      var fragment = document.createDocumentFragment();
      pieces.forEach(function (piece) { fragment.appendChild(piece); });
      node.parentNode.replaceChild(fragment, node);
    });
  }

  function boot() {
    wireTables();
    linkNames();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }

  window.NarutoCraft = { open: open, close: close };
})();
